import * as http from 'http';

async function test() {
  const server = http.createServer((req, res) => {
    console.log("SERVER RECEIVED REQUEST:", req.url);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ candidates: [{ content: { parts: [{ text: "local reply" }] }, finishReason: "STOP" }] }));
  });

  await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve));
  const port = (server.address() as any).port;
  console.log("Server listening on port", port);

  const vertex = new VertexAI({
    project: 'test-project',
    location: 'eu',
    apiEndpoint: `127.0.0.1:${port}`,
  });
  const model = vertex.getGenerativeModel({ model: 'gemini-1.5-flash' });
  try {
    const stream = await model.generateContentStream({ contents: [{ role: 'user', parts: [{ text: 'hi' }] }] });
    for await (const chunk of stream.stream) {
      console.log("CHUNK:", JSON.stringify(chunk));
    }
  } catch (e) {
    console.error("ERROR MESSAGE:", e.message);
  } finally {
    server.close();
  }
}
test();
